package com.example.usage;

import com.seed.javaInferredAuthRefreshToken.SeedJavaInferredAuthRefreshTokenClient;
import com.seed.javaInferredAuthRefreshToken.resources.auth.requests.GetTokenRequest;

public class Example {
    public static void main(String[] args) {
        SeedJavaInferredAuthRefreshTokenClient client = SeedJavaInferredAuthRefreshTokenClient
            .builder()
            .build();

        client.auth().getTokenWithRefreshToken(
            GetTokenRequest
                .builder()
                .refreshToken("my-refresh-token")
                .grantType("refresh_token")
                .scope("read")
                .build()
        );
    }
}

